function pageHead(title,subtitle){return`<div class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="head-side"><label class="learn-label"><input type="checkbox" id="learn" ${learn?'checked':''}> Guía de lectura</label></div></div>`}
function kpi(s,label,i){const l=last(s),d=change(s);const icons=['chart-line','chart-pie','building-columns','coins','scale-balanced','cubes'];return`<button type="button" class="kpi" data-detail="${esc(s?.id||'')}" data-derived="${s?.derived||''}" aria-label="Ver ${esc(label)}" aria-haspopup="dialog" title="${esc(label)} · ${period(s)} · ${esc(s?.unit||'')}" style="--stripe:${colors[i%colors.length]}"><span class="kpi-top"><span class="label"><i class="fa-solid fa-${icons[i%icons.length]}" aria-hidden="true"></i>${label}</span><i class="fa-solid fa-circle-info" aria-hidden="true"></i></span><strong class="value">${fmt(l?.value,Math.abs(l?.value||0)>999?0:2)}<span class="kpi-unit">${esc(shortUnit(s))}</span></strong><span class="kpi-bottom"><small>${period(s)}</small><span class="kpi-change"><span class="delta">${d&&finite(d.value)?`${d.value>0?'+':''}${fmt(d.value)} ${d.unit}`:'—'}</span><small>prev.</small></span></span></button>`}
