function timeChart(id,ss,{names=[],types=[],target=false,zero=false,index=false,area=false}={}){ss=ss.filter(Boolean);if(!ss.length){$('#'+id).innerHTML='<div class="empty">Serie no disponible en esta publicación.</div>';return}const units=[...new Set(ss.map(s=>unitKey(s)))];const dates=index?commonDates(ss,range):[];if(index&&!dates.length){$('#'+id).innerHTML='<div class="empty">No hay una fecha base común.</div>';return}const rows=windowRows(ss.map(s=>({s,rows:index?transform(s,'index',range,dates[0]):cut(s,'all')})),range);const opt=baseOption();opt.yAxis=units.slice(0,2).map((u,i)=>({...opt.yAxis,position:i?'right':'left',name:index?'Base 100':u.length<25?u:'',nameTextStyle:{fontSize:10,color:css('--muted')},scale:!zero&&!index&&ss.length===1&&!isRate(ss[0])}));if(units.length>1&&!index)opt.grid.right=65;opt.series=rows.map(({s,rows},i)=>({name:names[i]||s.name,type:types[i]||'line',data:withGaps(rows,s.frequency).map(o=>[o.date,o.value]),showSymbol:false,connectNulls:false,yAxisIndex:index?0:Math.min(units.indexOf(unitKey(s)),1),smooth:false,lineStyle:{width:2.2},emphasis:{focus:'series'},areaStyle:area&&i===0?{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:'#009bae35'},{offset:1,color:'#009bae02'}])}:undefined,barMaxWidth:18}));if(target){opt.series[0].markArea={silent:true,itemStyle:{color:theme()?'#13b9c815':'#009bae0d'},data:[[{yAxis:1},{yAxis:3}]]};opt.series[0].markLine={silent:true,symbol:'none',label:{formatter:'Meta 1–3%',position:'insideEndTop',color:css('--muted'),fontSize:10},lineStyle:{color:colors[0],type:'dashed',opacity:.6},data:[{yAxis:3}]}}chartRows.get(id).rows=rows;chart(id,opt)}
