function renderWorld(){const ipc=derived(f('CPIAUCSL'),'yoy','Inflación EE. UU.','%'),core=derived(f('CPILFESL'),'yoy','Inflación subyacente EE. UU.','%');const ks=[f('DFF'),f('DGS10'),f('T10Y2Y'),ipc,f('UNRATE'),f('DCOILWTICO')];$('#content').innerHTML=pageHead('Las condiciones externas','Tasas, actividad y mercados que conectan a Perú con la economía mundial.','MUNDO / TRANSMISIÓN ECONÓMICA')+`<div class="kpi-grid">${ks.map((s,i)=>kpi(s,['Fed Funds','Treasury 10 años','Pendiente 10a–2a','Inflación EE. UU.','Desempleo EE. UU.','Petróleo WTI'][i],i)).join('')}</div><div class="grid-two equal">`+panel('us-curve','Curva del Tesoro de EE. UU.','Rendimientos a 2, 10 y 30 años · %', ['DGS2','DGS10','DGS30'].map(f),{help:'Compara vencimientos en <strong>una misma fecha</strong>. Una pendiente negativa es una señal histórica, no una predicción segura de recesión.'})+panel('us-rates','El precio del dinero','Fed Funds efectiva y Treasury 10 años · %',[f('DFF'),f('DGS10')],{help:'La tasa Fed Funds es de muy corto plazo. El Treasury a 10 años incorpora expectativas y primas de riesgo; no tienen por qué moverse igual.'})+panel('us-inflation','Precios al consumidor en EE. UU.','Cambio interanual del IPC desestacionalizado · %',[ipc,core],{help:'Cálculo: (índice del mes / índice del mismo mes del año previo − 1) × 100. <strong>Sin rellenar meses faltantes.</strong>'})+panel('world-growth','Crecimiento en las grandes economías','PBI real · variación anual (%) · Banco Mundial',['WLD','LCN','USA','CHN','PER'].map(c=>wb(c,'NY.GDP.MKTP.KD.ZG')),{help:'Mundo y Latinoamérica son <strong>agregados oficiales</strong>. No se calculan como un promedio simple de países.'})+panel('us-dollar','Fortaleza del dólar','Índice amplio del dólar · enero 2006 = 100',[f('DTWEXBGS')],{help:'Un aumento refleja apreciación del dólar frente a una cesta ponderada. No es el índice DXY.'})+panel('world-oil','Petróleo y condiciones de oferta','WTI · US$ por barril',[f('DCOILWTICO')],{help:'Cotización spot diaria. El petróleo puede transmitir presiones a costos e inflación; este gráfico no identifica por sí solo sus causas.'})+`</div><div class="section-title"><h2>Trabajo, riesgo y expectativas</h2></div><section class="panel">${infoTable([f('UNRATE'),f('PAYEMS'),f('VIXCLS'),f('T10YIE'),f('GDPC1')])}</section>`;timeChart('us-rates',[f('DFF'),f('DGS10')],{names:['Fed Funds efectiva','Treasury 10a']});timeChart('us-inflation',[ipc,core],{names:['General','Subyacente']});timeChart('world-growth',['WLD','LCN','USA','CHN','PER'].map(c=>wb(c,'NY.GDP.MKTP.KD.ZG')),{names:['Mundo','Latinoamérica y Caribe','EE. UU.','China','Perú']});timeChart('us-dollar',[f('DTWEXBGS')],{names:['Dólar amplio'],area:true});timeChart('world-oil',[f('DCOILWTICO')],{names:['WTI'],area:true});const ss=['DGS2','DGS10','DGS30'].map(f).filter(Boolean),ds=commonDates(ss),latest=ds.at(-1);if(!latest){$('#us-curve').innerHTML='<div class="empty">Sin fechas comunes para la curva.</div>';return}const back=new Date(latest+'T00:00:00Z');back.setUTCDate(back.getUTCDate()-30);const prior=ds.filter(d=>d<=back.toISOString().slice(0,10)).at(-1);const opts=baseOption();delete opts.dataZoom;opts.xAxis={type:'category',data:['2 años','10 años','30 años'],boundaryGap:false,axisLine:{lineStyle:{color:css('--line')}},axisLabel:{color:css('--muted')}};opts.yAxis.scale=true;opts.grid.bottom=38;opts.series=[prior,latest].filter(Boolean).map((d,i)=>({name:date(d,'daily'),type:'line',data:ss.map(s=>s.observations.find(o=>o.date===d).value),symbolSize:9,lineStyle:{width:2,type:i?'solid':'dashed'},label:{show:true,position:'top',formatter:p=>fmt(p.value)+'%',color:css('--muted'),fontSize:11}}));chartRows.get('us-curve').rows=ss.map(s=>({s,rows:s.observations.filter(o=>o.date===latest||o.date===prior)}));chart('us-curve',opts)}
function renderExplorer(){if(!selected.length)selected=[b('inflation')?.id,b('core')?.id].filter(Boolean);const ss=selected.map(id=>series.find(s=>s.id===id)).filter(Boolean);$('#content').innerHTML=pageHead('Tu mesa de análisis','Busca indicadores, compara trayectorias y vuelve al dato original.','EXPLORADOR / SERIES HISTÓRICAS')+`<div class="explorer"><aside class="catalog panel"><div class="catalog-head"><h2>Catálogo de indicadores</h2><input id="search" type="search" placeholder="Inflación, cobre, Perú…" aria-label="Buscar series"><select id="provider-filter" aria-label="Filtrar por fuente"><option value="">Todas las fuentes</option><option>BCRP</option><option>FRED</option><option>World Bank</option></select><small>${series.length} series · máximo 4 a la vez</small></div><div class="catalog-list" id="catalog-list"></div></aside><div class="explorer-main"><div class="selection">${ss.map((s,i)=>`<button data-remove="${s.id}" style="border-left:3px solid ${colors[i]}">${esc(s.countryName||s.country)} · ${esc(s.name)} <span>×</span></button>`).join('')}</div><section class="panel"><div class="explorer-controls"><label>Mostrar <select id="transform"><option value="level">Valor original</option><option value="index">Índice base 100</option><option value="yoy">Variación interanual (%)</option><option value="diff">Cambio absoluto</option></select></label><label>Gráfico <select id="chart-type"><option value="line">Líneas</option><option value="bar">Barras</option><option value="scatter">Dispersión · 2 series</option></select></label><button data-table="explore-chart">Datos</button><button data-png="explore-chart">PNG</button><button id="reset-explorer">Restablecer</button></div><div id="explore-chart" class="chart chart-renderer" role="img" aria-label="Comparación personalizada"></div><div id="explore-note" class="chart-note explore-note"></div></section><div id="explore-stats"></div><section class="panel"><div class="panel-head"><h2>Series seleccionadas</h2></div>${infoTable(ss)}</section><div class="reading"><strong>Una comparación con contexto.</strong> Se exige la misma frecuencia. Base 100 requiere niveles positivos y una fecha común; no aplica a tasas. La correlación mide asociación en los periodos coincidentes, no causalidad.</div></div></div>`;$('#transform').value=mode;$('#chart-type').value=chartType;renderCatalog();renderExploreChart()}
function renderCatalog(){const q=($('#search')?.value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),provider=$('#provider-filter')?.value;$('#catalog-list').innerHTML=series.filter(s=>(!provider||s.provider===provider)&&`${s.name} ${s.countryName} ${s.sourceCode} ${s.provider}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)).map(s=>`<button class="series-item" data-select="${s.id}" aria-pressed="${selected.includes(s.id)}">${esc(s.name)}<span>${esc(s.countryName||s.country)} · ${freqs[s.frequency]} · ${esc(s.provider)}</span></button>`).join('')||'<div class="empty">Sin coincidencias.</div>'}
function renderExploreChart(){const old=charts.find(c=>c.__chartId==='explore-chart');if(old){old.dispose();charts=charts.filter(c=>c!==old)}const ss=selected.map(id=>series.find(s=>s.id===id)).filter(Boolean);const fail=t=>{$('#explore-chart').innerHTML=`<div class="empty">${t}</div>`;$('#explore-note').textContent='Ajusta la selección para continuar.';$('#explore-stats').innerHTML='';chartRows.delete('explore-chart')};$('#explore-chart').innerHTML='';if(!ss.length)return fail('Selecciona al menos una serie.');if(new Set(ss.map(s=>s.frequency)).size>1)return fail('Estas series tienen distintas frecuencias. Selecciona series de la misma frecuencia para compararlas.');if(mode==='index'&&ss.some(s=>isRate(s)||cut(s,range).some(o=>o.value<=0)))return fail('Base 100 solo admite niveles estrictamente positivos, como índices, precios o cantidades.');if(mode==='yoy'&&ss.some(s=>isRate(s)||s.observations.some(o=>o.value<=0)))return fail('Una tasa ya expresada en porcentaje se compara en puntos porcentuales. Usa “Cambio absoluto”.');if(['yoy','diff'].includes(mode)&&ss.some(s=>s.frequency==='daily'))return fail('Para cambios por periodo selecciona series mensuales, trimestrales o anuales. Las series diarias pueden compararse en nivel o base 100.');const dates=commonDates(ss,range),baseDate=dates[0];if(mode==='index'&&!baseDate)return fail('No hay una fecha base común para las series.');let rows=windowRows(ss.map(s=>({s,rows:transform(s,mode,'all',baseDate)})),range);const units=[...new Set(ss.map(s=>unitKey(s)))];if(mode==='diff'&&units.length>1)return fail('El cambio absoluto requiere series con la misma unidad. Compara sus niveles con dos ejes o elige series homogéneas.');if(mode==='level'&&units.length>2)return fail('Selecciona como máximo dos unidades diferentes o usa base 100 para comparar niveles.');chartRows.set('explore-chart',{title:'Comparación de indicadores',ss,rows,mode});const opt=baseOption();opt.legend.top=5;opt.grid.top=60;opt.grid.bottom=65;let aligned=rows.length===2?pairs(rows[0].rows,rows[1].rows):[],rho=aligned.length>=12?correlation(aligned):null;if(chartType==='scatter'){if(ss.length!==2)return fail('La dispersión necesita exactamente dos series.');if(aligned.length<3)return fail('No hay suficientes observaciones coincidentes para la dispersión.');chartRows.get('explore-chart').rows=ss.map((s,i)=>({s,rows:aligned.map(p=>({date:p.date,value:i?p.y:p.x}))}));delete opt.dataZoom;delete opt.legend;opt.grid={left:78,right:35,top:30,bottom:65};opt.xAxis={...opt.yAxis,type:'value',name:ss[0].name,nameLocation:'middle',nameGap:34,scale:true};opt.yAxis={...opt.yAxis,scale:true,name:ss[1].name,nameLocation:'middle',nameRotate:90,nameGap:48,nameTextStyle:{fontSize:10}};opt.tooltip={...opt.tooltip,trigger:'item',formatter:p=>`${date(p.data[2],ss[0].frequency)}<br>${esc(ss[0].name)}: ${fmt(p.data[0])}<br>${esc(ss[1].name)}: ${fmt(p.data[1])}`};opt.series=[{type:'scatter',symbolSize:8,itemStyle:{opacity:.7},data:aligned.map(r=>[r.x,r.y,r.date])}]}else{opt.yAxis=(mode==='level'?units:['value']).map((u,i)=>({...opt.yAxis,position:i?'right':'left',scale:chartType!=='bar',name:mode==='index'?'Base 100':mode==='yoy'?'%':u==='value'?'':u,nameTextStyle:{fontSize:10},axisLabel:{color:css('--muted'),fontSize:11}}));if(units.length>1&&mode==='level')opt.grid.right=65;opt.series=rows.map(({s,rows},i)=>({type:chartType,name:(s.countryName||s.country)+' · '+s.name,data:withGaps(rows,s.frequency).map(o=>[o.date,o.value]),connectNulls:false,showSymbol:false,yAxisIndex:mode==='level'?units.indexOf(unitKey(s)):0,lineStyle:{width:2},barMaxWidth:16}))}chart('explore-chart',opt);$('#explore-note').innerHTML=`<span>${mode==='index'?`Base común: <strong>${date(baseDate,ss[0].frequency)}</strong>. `:''}${mode==='diff'?`Cambio frente al periodo anterior, en ${ss.some(isRate)?'puntos porcentuales':'la unidad original'}. `:''}${mode==='yoy'?'Cambio frente al mismo periodo del año anterior. ':''}${units.length>1&&mode==='level'?'Dos escalas: izquierda y derecha. ':''}Frecuencia ${freqs[ss[0].frequency].toLowerCase()} · ${rows.map(x=>x.rows.filter(o=>finite(o.value)).length).join(' / ')} observaciones.</span>`;if(ss.length===1){const vals=rows[0].rows.map(o=>o.value).filter(finite);$('#explore-stats').innerHTML=`<div class="stat-row">${[['Observaciones',String(vals.length)],['Mínimo',fmt(Math.min(...vals))],['Máximo',fmt(Math.max(...vals))],['Promedio',fmt(vals.reduce((a,b)=>a+b,0)/vals.length)]].map(([l,v])=>`<div class="stat"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div>`}else $('#explore-stats').innerHTML=`<div class="reading">${ss.length===2?`<strong>Correlación de Pearson: ${fmt(rho)}</strong> · ${aligned.length} periodos coincidentes. ${rho===null?'Se requieren al menos 12 pares y varianza no nula.':'En niveles, las tendencias comunes pueden producir correlaciones engañosas.'}`:'Hasta cuatro series, con las fechas y unidades originales.'}</div>`}
function windowRows(groups,years){if(years==='all')return groups;const latest=groups.flatMap(g=>g.rows.map(o=>o.date)).sort().at(-1);if(!latest)return groups;const d=new Date(latest+'T00:00:00Z');d.setUTCFullYear(d.getUTCFullYear()-Number(years));const start=d.toISOString().slice(0,10);return groups.map(g=>({...g,rows:g.rows.filter(o=>o.date>=start)}))}
function unitKey(s){return isRate(s)&&s.unit!=='p.p.'?'%':s.unit}
function withGaps(rows,freq){if(!rows.length||freq==='daily')return rows;const m=new Map(rows.map(o=>[o.date,o.value])),step={monthly:1,quarterly:3,annual:12}[freq];if(!step)return rows;const out=[],d=new Date(rows[0].date+'T00:00:00Z'),end=rows.at(-1).date;while(d.toISOString().slice(0,10)<=end){const key=d.toISOString().slice(0,10);out.push({date:key,value:m.has(key)?m.get(key):null});d.setUTCMonth(d.getUTCMonth()+step)}return out}
function stale(s){const l=last(s);if(!l)return true;const age=(Date.now()-Date.parse(l.date))/86400000;return age>({daily:10,monthly:105,quarterly:230,annual:1000}[s.frequency]||1000)}
function statusLabel(s){return!last(s)?'Sin cobertura':s.status==='retained'?'Último válido':stale(s)?'Con rezago':'Disponible'}
function renderSources(){const providers=[['BCRP','BCRPData','Actividad, precios, sector externo y mercados peruanos. API pública, sin clave.','https://estadisticas.bcrp.gob.pe/estadisticas/series/ayuda/api'],['FRED','Federal Reserve Bank of St. Louis','Series de EE. UU. y mercados. Descarga pública CSV; conserva las fuentes originales de cada indicador.','https://fred.stlouisfed.org/'],['World Bank','Banco Mundial · WDI','Comparaciones anuales. Incluye países y agregados oficiales; el rezago varía por indicador.','https://data.worldbank.org/'],['MEF','MEF · vía BCRPData','Deuda y estadísticas fiscales del sector público, distribuidas por BCRP. No se presenta como conexión directa con el portal MEF.','https://www.mef.gob.pe/']];const covered=series.filter(s=>last(s)).length;$('#content').innerHTML=pageHead('Fuentes, fechas y metodología','Distingue cuándo se descargó una serie de cuándo ocurrió el dato económico.','TRAZABILIDAD / CALIDAD')+`<div class="stat-row">${[['Series con datos',covered],['Series configuradas',series.length],['Observaciones',fmt(series.reduce((a,s)=>a+s.observations.length,0),0)],['Economías y agregados',new Set(series.map(s=>s.country)).size]].map(([l,v])=>`<div class="stat"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="grid-two equal">${providers.map(([p,n,d,url])=>{const ss=p==='MEF'?series.filter(s=>s.originalSource?.includes('MEF')):series.filter(s=>s.provider===p);return`<section class="panel source-card"><div class="provider-title"><div><div class="provider-name">${p==='MEF'?'FUENTE PRIMARIA':esc(p)}</div><h2>${n}</h2></div><a href="${url}" target="_blank" rel="noopener">Fuente ↗</a></div><p>${d}</p><div class="health-line"><span>${ss.filter(s=>last(s)).length} series con datos</span><span>${ss.filter(s=>!last(s)).length} sin cobertura</span><span>${ss.filter(s=>s.status==='retained').length} conservadas</span></div></section>`}).join('')}</div><div class="section-title"><h2>Estado de cada indicador</h2><input id="health-search" type="search" placeholder="Filtrar series…" aria-label="Filtrar estado de series"></div><section class="panel"><div class="table-scroll"><table><thead><tr><th>Serie / economía</th><th>Fuente</th><th>Frecuencia</th><th>Último dato</th><th>Descarga</th><th>Estado</th></tr></thead><tbody id="health-rows">${healthRows('')}</tbody></table></div></section><div class="section-title"><h2>Criterios de lectura</h2></div><section class="panel guide">${[['Periodos y revisiones','Las fechas guardadas representan el inicio del mes, trimestre o año observado; no la fecha de publicación. La sincronización vuelve a consultar la historia para recoger revisiones. Esta base muestra la última versión disponible, no lo que se conocía en cada fecha histórica.'],['Comparaciones y unidades','Inflación, crecimiento y tasas expresadas en porcentaje cambian en puntos porcentuales. Un punto porcentual equivale a 100 puntos básicos. La inflación anual del Banco Mundial es una variación de promedios anuales; no equivale a la inflación de diciembre. La inflación peruana mostrada corresponde a Lima Metropolitana.'],['Fiscal y deuda','La deuda SPNF del BCRP/MEF y la deuda del gobierno central del Banco Mundial tienen coberturas distintas. El resultado fiscal acumulado 12 meses es un flujo; la deuda es un saldo. No se suman porcentajes entre periodos.'],['Índices, faltantes y correlación','No se imputan valores ni se rellenan ausencias con cero. Base 100 toma una fecha común y divide cada nivel por su valor inicial. La correlación usa solo fechas coincidentes, al menos 12 pares; no demuestra causalidad.'],['Sincronización y rezagos','GitHub Actions consulta las fuentes cada día. La web revisa la versión publicada cada cinco minutos y al regresar a la pestaña. Actualizar recarga el archivo publicado; no dispara una descarga del proveedor. El indicador de rezago es una alerta orientativa: más de 10 días en diaria, 105 mensual, 230 trimestral y 1000 anual, medidos desde inicio del periodo.'],['Expectativas y mercados','DGS son rendimientos de bonos, no precios. La inflación implícita a 10 años incluye primas de riesgo y liquidez. VIX no mide una probabilidad de recesión. Los indicadores de recesión NBER se determinan retrospectivamente.']].map(([t,p])=>`<details><summary>${t}</summary><p>${p}</p></details>`).join('')}</section>`}
function healthRows(q){return series.filter(s=>`${s.name} ${s.countryName} ${s.sourceCode}`.toLowerCase().includes(q.toLowerCase())).map(s=>`<tr><td><button class="link-button" data-detail="${s.id}">${esc(s.name)}</button><br><small>${esc(s.countryName)} · ${s.sourceCode}</small></td><td>${esc(s.provider)}</td><td>${freqs[s.frequency]}</td><td>${period(s)}</td><td>${date(s.fetchedAt?.slice(0,10),'daily')}</td><td class="${!last(s)||stale(s)||s.status==='retained'?'health-warn':'health-ok'}">${statusLabel(s)}</td></tr>`).join('')}
function render(){if(!data)return;colors.splice(0,colors.length,...['--cyan','--blue','--purple','--amber','--red','--green'].map(css),'#5da0c6','#bb6b92');dispose();$('#navigation').innerHTML=tabs.map(([id,label],i)=>`<button class="nav-button" data-view="${id}" aria-current="${view===id?'page':'false'}"><i class="fa-solid fa-${['chart-pie','earth-americas','globe','chart-line','database'][i]}" aria-hidden="true"></i>${label}</button>`).join('');({peru:renderPeru,latam:renderLatam,world:renderWorld,explorer:renderExplorer,sources:renderSources}[view]||renderPeru)();const old=series.filter(s=>s.status==='retained').length;$('#health-label').textContent=old?'Parcial':'Disponible';$('#health').dataset.status=old?'WARNING':'OK';$('#health').title=`${series.filter(s=>last(s)).length} series disponibles · ${old} conservadas. Ver fuentes y fechas.`;$('#build-info').textContent=`Descarga: ${new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(data.fetchedAt))} · Lima`;if((Date.now()-Date.parse(data.fetchedAt))/86400000>2)$('#content').insertAdjacentHTML('afterbegin','<div class="error-notice">La publicación tiene más de 48 horas. Revisa la sincronización en GitHub Actions; las fechas de los datos económicos se muestran por separado.</div>')}
function downloadBlob(content,name,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCsv(rows,name='indicadores'){const header=['serie','indicador','economia','fecha','valor','unidad','transformacion','fuente','url'];const out=[header];const emitted=new Set();for(const {s,rows:obs,mode:explicitMode}of rows){const m=explicitMode||s.derived||'level';for(const o of obs){const key=s.id+'|'+o.date+'|'+m;if(emitted.has(key))continue;emitted.add(key);out.push([s.sourceCode,s.name,s.countryName,o.date,o.value??'',m==='index'?'Base 100':m==='yoy'?'%':m==='diff'&&isRate(s)?'pp':s.unit,m||'level',s.provider,s.sourceUrl])}}const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';downloadBlob('\ufeff'+out.map(r=>r.map(cell).join(';')).join('\r\n'),`treasury-macro-${name}.csv`)}
function dataRows(config){return config.rows||config.ss.map(s=>({s,rows:cut(s,range)}))}
function showDialog(title,html){$('#detail-title').textContent=title;$('#detail-body').innerHTML=html;$('#detail').showModal();document.body.style.overflow='hidden';document.documentElement.classList.add('chart-export-open')}
function showData(id){const config=chartRows.get(id);if(!config)return;const rows=dataRows(config),mode=config.mode||config.ss.find(s=>s.derived)?.derived;showDialog(config.title,`<div class="row-filters"><button id="modal-csv">Descargar CSV completo</button><small>${rows.reduce((a,x)=>a+x.rows.length,0)} observaciones en la selección${mode&&mode!=='level'?' · Transformación: '+esc(mode):''}</small></div>${rows.map(({s,rows:obs})=>`<h3>${esc(s.name)} · ${esc(s.countryName)}</h3><p class="muted">${source(s)} · <a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">Abrir fuente oficial ↗</a></p><div class="table-scroll"><table><thead><tr><th>Periodo</th><th class="numeric">Valor ${mode&&mode!=='level'?'transformado':'original'}</th></tr></thead><tbody>${obs.slice().reverse().map(o=>`<tr><td>${date(o.date,s.frequency)}</td><td class="numeric">${fmt(o.value,4)}</td></tr>`).join('')}</tbody></table></div>`).join('<br>')}`);$('#modal-csv').onclick=()=>exportCsv(rows.map(r=>({...r,mode})),id)}
function detail(id,derivedMode=''){let s=series.find(s=>s.id===id);if(!s)return;if(derivedMode==='yoy')s=derived(s,'yoy','Inflación EE. UU. · variación interanual','%');showDialog(s.name,`<div class="metadata"><div><span>Economía</span>${esc(s.countryName)}</div><div><span>Unidad</span>${esc(s.unit)}</div><div><span>Frecuencia</span>${freqs[s.frequency]}</div><div><span>Última observación</span>${period(s)}</div><div><span>Fuente / código</span>${source(s)}</div><div><span>Estado</span>${statusLabel(s)}</div></div><p class="muted">${s.derived?'Cálculo: (índice / índice del mismo mes del año previo − 1) × 100. Índice original: ':''}${esc(s.description||s.name)}${s.originalSource?'<br>Fuente primaria: '+esc(s.originalSource):''}</p><div class="row-filters"><a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener">Fuente oficial ↗</a><button id="detail-csv">Descargar CSV</button><button id="detail-explore">Llevar al explorador</button></div><div id="detail-chart" class="detail-chart" role="img" aria-label="Historia del indicador"></div><p class="muted">La fecha corresponde al periodo económico. Descarga: ${date(s.fetchedAt?.slice(0,10),'daily')}.</p>`);chartRows.set('detail-chart',{title:s.name,ss:[s]});timeChart('detail-chart',[s],{names:[s.name]});$('#detail-csv').onclick=()=>exportCsv([{s,rows:cut(s,range)}],s.id);$('#detail-explore').onclick=()=>{$('#detail').close();selected=[s.id];mode=s.derived||'level';view='explorer';location.hash=view;render()}}
function expand(id){const c=charts.find(c=>c.__chartId===id),meta=chartRows.get(id);if(!c||!meta)return;const option=c.getOption();showDialog(meta.title,'<div id="expanded-chart" class="detail-chart" role="img" aria-label="Gráfico ampliado"></div>');chart('expanded-chart',option)}
function png(id){const c=charts.find(c=>c.__chartId===id),meta=chartRows.get(id);if(!c)return;const raw=new Image;raw.onload=()=>{const canvas=document.createElement('canvas');canvas.width=raw.width;canvas.height=raw.height+130;const ctx=canvas.getContext('2d');ctx.fillStyle=css('--panel');ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle=css('--ink');ctx.font='bold 28px Segoe UI';ctx.fillText(meta?.title||'Treasury Hub',35,45);ctx.drawImage(raw,0,65);ctx.fillStyle=css('--muted');ctx.font='18px Segoe UI';ctx.fillText(`Treasury Hub · ${[...new Set((meta?.ss||[]).map(s=>s.provider))].join(' / ')} · Historia: ${range==='all'?'completa':range+' años'}`,35,canvas.height-22);const a=document.createElement('a');a.download=`treasury-macro-${id}.png`;a.href=canvas.toDataURL('image/png');a.click()};raw.src=c.getDataURL({pixelRatio:2,backgroundColor:css('--panel')})}
async function refresh(manual=false){if(loading||(!manual&&Date.now()-lastCheck<300000))return;loading=true;lastCheck=Date.now();if(manual)$('#refresh').disabled=true;try{const mr=await fetch('./data/manifest.json?v='+Date.now(),{cache:'no-store'});if(!mr.ok)throw Error('No se pudo consultar la versión publicada.');const manifest=await mr.json();if(data&&manifest.version===data.version){if(manual)toast('Ya tienes la última publicación disponible.');return}const r=await fetch('./data/snapshot.json?v='+encodeURIComponent(manifest.version),{cache:'no-store'});if(!r.ok)throw Error('No se pudo descargar la publicación.');const next=validateSnapshot(await r.json());if(next.version!==manifest.version)throw Error('La publicación está cambiando; se conserva la versión anterior.');if(!data||next.version!==data.version||next.fetchedAt!==data.fetchedAt){data=next;series=data.series;render();if(manual)toast('Publicación recargada en todas las vistas.')}else if(manual)toast('Ya tienes la última publicación disponible.')}catch(e){if(!data)$('#content').innerHTML=`<div class="error-notice">${esc(e.message)} Sirve la carpeta mediante HTTP o abre la web publicada. <button id="retry">Reintentar</button></div>`;else if(manual)toast('No se pudo actualizar. Se conserva la versión que estabas consultando.')}finally{loading=false;$('#refresh').disabled=false}}
$('#content').addEventListener('click',e=>{const t=e.target.closest('button,[data-detail]');if(!t)return;if(t.dataset.detail)return detail(t.dataset.detail,t.dataset.derived||'');if(t.dataset.table)return showData(t.dataset.table);if(t.dataset.png)return png(t.dataset.png);if(t.dataset.expand)return expand(t.dataset.expand);if(t.dataset.country){if(countries.includes(t.dataset.country)){if(countries.length===1)return toast('Mantén al menos un país.');countries=countries.filter(c=>c!==t.dataset.country)}else countries.push(t.dataset.country);year='';render();return}if(t.id==='common-year'){year=commonDates(countries.map(c=>wb(c,metric)).filter(Boolean)).at(-1)||'';if(!year)return toast('No existe un año con datos para todos los países seleccionados.');render();return}if(t.dataset.select){const id=t.dataset.select;if(selected.includes(id))selected=selected.filter(s=>s!==id);else if(selected.length<4)selected.push(id);else return toast('Puedes comparar hasta cuatro series.');render();return}if(t.dataset.remove){selected=selected.filter(s=>s!==t.dataset.remove);if(!selected.length)selected=[b('inflation').id];render();return}if(t.id==='reset-explorer'){selected=[b('inflation').id,b('core').id];mode='level';chartType='line';render()}if(t.id==='retry')refresh(true)});
$('#content').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[data-detail]')){e.preventDefault();detail(e.target.dataset.detail,e.target.dataset.derived||'')}});
$('#content').addEventListener('change',e=>{if(e.target.id==='learn'){learn=e.target.checked;save('learn',learn);render()}if(e.target.id==='wb-metric'){metric=e.target.value;year='';render()}if(e.target.id==='wb-year'){year=e.target.value;render()}if(e.target.id==='provider-filter')renderCatalog();if(e.target.id==='transform'){mode=e.target.value;renderExploreChart()}if(e.target.id==='chart-type'){chartType=e.target.value;renderExploreChart()}});
$('#content').addEventListener('input',e=>{if(e.target.id==='search')renderCatalog();if(e.target.id==='health-search')$('#health-rows').innerHTML=healthRows(e.target.value)});
$('#navigation').onclick=e=>{const t=e.target.closest('[data-view]');if(t){view=t.dataset.view;location.hash=view;render();window.scrollTo({top:0,behavior:'smooth'})}};
$('#range').onchange=e=>{range=e.target.value;save('range',range);render()};$('#health').onclick=()=>{view='sources';location.hash=view;render()};$('#refresh').onclick=()=>refresh(true);$('#download').onclick=()=>{const rows=[...chartRows.values()].flatMap(c=>dataRows(c).map(r=>({...r,mode:c.mode})));if(!rows.length&&view==='sources')exportCsv(series.map(s=>({s,rows:s.observations})),'catalogo');else exportCsv(rows,view)};
$('#close-dialog').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>{document.body.style.overflow='';document.documentElement.classList.remove('chart-export-open');window.dispatchEvent(new Event('sbs:scroll-restored'));for(const id of['detail-chart','expanded-chart']){const c=charts.find(c=>c.__chartId===id);if(c){c.dispose();charts=charts.filter(x=>x!==c)}chartRows.delete(id)}});$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
window.addEventListener('resize',()=>charts.forEach(c=>c.resize()));window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==view&&tabs.some(t=>t[0]===next)){view=next;render()}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});window.addEventListener('focus',()=>refresh());setInterval(()=>{if(!document.hidden)refresh()},300000);initTreasuryShell(()=>{if(data)render()});refresh(true);

const rangeOptions=['3','5','10','all'];
function updateRange(value){range=value;$('#range').value=value;save('range',range);render();syncRangeButtons()}
function syncRangeButtons(){const i=rangeOptions.indexOf(range);$('#range-prev').disabled=i<=0;$('#range-next').disabled=i>=rangeOptions.length-1}
$('#range-prev').onclick=()=>updateRange(rangeOptions[Math.max(0,rangeOptions.indexOf(range)-1)]);
$('#range-next').onclick=()=>updateRange(rangeOptions[Math.min(rangeOptions.length-1,rangeOptions.indexOf(range)+1)]);
$('#range-all').onclick=()=>updateRange('all');$('#range').onchange=e=>updateRange(e.target.value);syncRangeButtons();
function openSearch(){view='explorer';location.hash=view;render();$('#search')?.focus()}
$('#search-open').onclick=openSearch;
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#detail').open)$('#detail').close();openSearch()}});
function openSources(){view='sources';location.hash=view;render()}
$('#info').onclick=openSources;$('#footer-info').onclick=openSources;
$('#switch-app').onclick=()=>showDialog('Treasury Hub',`<div class="tool-links"><a class="tool-link" href="https://walterchb.github.io/data-sbs/"><i class="fa-solid fa-building-columns" aria-hidden="true"></i><div><strong>Información Financiera SBS</strong><small>Bancos, estados financieros e indicadores</small></div></a><a class="tool-link" href="https://tc.treasuryhub.app/"><i class="fa-solid fa-coins" aria-hidden="true"></i><div><strong>TC Treasury Hub</strong><small>Tipo de cambio contable y mercados</small></div></a></div>`);
